\pset format unaligned
\pset tuples_only on
select 'DEFINER total: ' || count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef;
select 'DEFINER sin search_path fijo: ' || coalesce(string_agg(p.oid::regprocedure::text, ', '), 'ninguna') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and not coalesce(p.proconfig,'{}') @> array['search_path=""'] and not exists (select 1 from unnest(coalesce(p.proconfig,'{}')) c where c like 'search_path=%');
select 'DEFINER con search_path no vacío: ' || coalesce(string_agg(p.oid::regprocedure::text || ' ' || array_to_string(p.proconfig, ','), '; '), 'ninguna') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and exists (select 1 from unnest(coalesce(p.proconfig,'{}')) c where c like 'search_path=%' and c <> 'search_path=""');
select 'DEFINER ejecutables por anon/PUBLIC: ' || coalesce(string_agg(p.oid::regprocedure::text, ', '), 'ninguna') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and (has_function_privilege('anon', p.oid, 'execute'));
select 'DEFINER ejecutables por authenticated: ' || coalesce(string_agg(p.proname, ', ' order by p.proname), 'ninguna') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef and has_function_privilege('authenticated', p.oid, 'execute');
select 'DEFINER propietarios: ' || string_agg(distinct pg_get_userbyid(p.proowner), ', ') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef;
select 'funciones NO definer ejecutables por anon/authenticated (public): ' || coalesce(string_agg(p.proname, ', ' order by p.proname), 'ninguna') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and not p.prosecdef and p.prokind='f' and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')) and p.prorettype <> 'trigger'::regtype;
